  (32, 5, $svjson${"evidence":{"limitation":"Complete all required fields before submitting. Version 3 (CERT-REFINE-01) adds the certificate QA refinement data slots. Version 4 (QAFIX-01) enters the application purpose once with a language choice, seats Bangla/English companion fields beside each other, unifies the document-language label and applies the live-QA spelling corrections. Version 5 (QAFIX-07) seats the household size and dependant count beside the declared income, names the earning person (Bangla and English) ahead of the occupation the certificate attests, and makes the documents step name the income and hardship evidence and require at least one upload. The certificate prints only the income and the earner's occupation, so the household figures and the earner's name are office evidence.","source":"audit/evidence/s-32.json","status":"proposed"},"sections":[{"fields":[{"constraints":{"max":1000000000,"min":0,"required":true},"evidence":{"status":"proposed"},"id":"monthly_household_income_bdt","label":{"bn":"মাসিক পারিবারিক আয় (টাকা)","en":"Monthly household income (BDT)"},"type":"number"},{"constraints":{"max":100,"min":1,"required":true},"id":"household_member_count","label":{"bn":"পরিবারের সদস্য সংখ্যা","en":"Household members (family size)"},"type":"number"},{"constraints":{"max":100,"min":0,"required":true},"id":"dependant_count","label":{"bn":"নির্ভরশীল সদস্য সংখ্যা","en":"Dependant members"},"type":"number"},{"constraints":{"maxLength":1500,"minLength":2,"required":true},"evidence":{"status":"proposed"},"id":"hardship_details","label":{"bn":"অস্বচ্ছলতার বিবরণ","en":"Financial hardship details"},"type":"textarea"},{"children":[{"constraints":{"maxLength":150,"minLength":2,"required":true},"evidence":{"status":"proposed"},"id":"description","label":{"bn":"নথির বিবরণ","en":"Document description"},"type":"text"},{"constraints":{"acceptedMimeTypes":["application/pdf","image/png","image/jpeg"],"maxBytes":2097152,"required":true},"evidence":{"status":"proposed"},"id":"file","label":{"bn":"নথি","en":"Document"},"type":"attachment"}],"constraints":{"maxRows":5,"minRows":1},"description":{"bn":"আয়ের প্রমাণ (বেতন রশিদ বা নিয়োগকর্তার প্রত্যয়ন) ও আর্থিক দুরবস্থার প্রমাণের স্ক্যান কপি আপলোড করুন (PDF, PNG বা JPEG; সর্বোচ্চ 2 MiB)।","en":"Upload scanned copies of income proof (a pay slip or an employer's letter) and evidence of the financial hardship (PDF, PNG or JPEG; maximum 2 MiB)."},"evidence":{"status":"proposed"},"id":"supporting_documents","label":{"bn":"সহায়ক নথি","en":"Supporting documents"},"type":"repeatable"},{"constraints":{"maxLength":160,"required":true},"id":"earner_name_bn","label":{"bn":"উপার্জনকারীর নাম (বাংলা)","en":"Earner's name (Bangla)"},"type":"text"},{"constraints":{"maxLength":160,"required":true},"id":"earner_name","label":{"bn":"উপার্জনকারীর নাম (ইংরেজি)","en":"Earner's name (English)"},"type":"text"},{"constraints":{"maxLength":500,"required":false},"evidence":{"status":"proposed"},"id":"earner_occupation_bn","label":{"bn":"উপার্জনক্ষম ব্যক্তির পেশা (বাংলা)","en":"Earner occupation (Bangla)"},"type":"text"},{"constraints":{"maxLength":500,"required":false},"evidence":{"status":"proposed"},"id":"earner_occupation_en","label":{"bn":"উপার্জনক্ষম ব্যক্তির পেশা (ইংরেজি)","en":"Earner occupation (English)"},"type":"text"}],"id":"service_details","title":{"bn":"সেবার তথ্য","en":"Service details"}},{"fields":[{"constraints":{"required":true},"evidence":{"status":"proposed"},"id":"address_source","label":{"bn":"প্রযোজ্য ঠিকানা","en":"Applicable citizen address"},"options":[{"label":{"bn":"স্থায়ী ঠিকানা","en":"Permanent address"},"value":"permanent"},{"label":{"bn":"বর্তমান ঠিকানা","en":"Present address"},"value":"present"}],"type":"select"},{"constraints":{"maxLength":500,"minLength":2,"required":true},"evidence":{"status":"proposed"},"id":"purpose","label":{"bn":"আবেদনের উদ্দেশ্য","en":"Purpose of application"},"type":"text"},{"constraints":{"required":true},"evidence":{"status":"proposed"},"id":"p